    def fetch_currencies(self, params={}) -> Currencies:
        """
        fetches all available currencies on the exchange

        https://dev.dreamdex.somnia.host/v0/.well-known/oapi.json

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: an associative dictionary of currencies
        """
        response = self.publicGetV0Currencies(params)
        #
        #     {
        #         "currencies": [
        #             {"id": "0xe8F76...", "code": "SOMI", "name": "SOMI", "decimals": "18"},
        #             {"id": "0xB4AFC...", "code": "USDC", "name": "USDC", "decimals": "6"}
        #         ]
        #     }
        #
        currencies = self.safe_list(response, 'currencies', [])
        result: dict = {}
        for i in range(0, len(currencies)):
            currency = currencies[i]
            id = self.safe_string(currency, 'code')
            code = self.safe_currency_code(id)
            name = self.safe_string(currency, 'name')
            decimals = self.safe_integer(currency, 'decimals')
            precision = None
            if decimals is not None:
                precision = self.parse_number(self.parse_precision(self.number_to_string(decimals)))
            result[code] = self.safe_currency_structure({
                'id': id,
                'code': code,
                'name': name,
                'type': 'crypto',
                'active': True,
                'deposit': True,
                'withdraw': True,
                'fee': None,
                'precision': precision,
                'limits': {
                    'deposit': {
                        'min': None,
                        'max': None,
                    },
                    'withdraw': {
                        'min': None,
                        'max': None,
                    },
                },
                'networks': {},
                'info': currency,
            })
        return result

